const MAPS_BASE_URL = "https://maps.googleapis.com/maps/api";

if (!process.env.GOOGLE_MAPS_API_KEY) {
  throw new Error("GOOGLE_MAPS_API_KEY is missing from .env.local");
}

// Exported so service modules (e.g. static-maps.ts) can read the key
// after the env-guard above has already run.
export const MAPS_API_KEY = process.env.GOOGLE_MAPS_API_KEY!;

type MapsApiStatus =
  | "OK"
  | "ZERO_RESULTS"
  | "NOT_FOUND"
  | "MAX_WAYPOINTS_EXCEEDED"
  | "INVALID_REQUEST"
  | "REQUEST_DENIED"
  | "OVER_DAILY_LIMIT"
  | "OVER_QUERY_LIMIT"
  | "UNKNOWN_ERROR";

/**
 * Thin fetch wrapper for Google Maps REST APIs.
 *
 * Google Maps returns HTTP 200 even for application-level errors — this helper
 * checks the `status` field and throws a descriptive error for any non-OK,
 * non-ZERO_RESULTS status so callers don't have to.
 */
export async function mapsRequest<
  T extends { status?: MapsApiStatus; error_message?: string },
>(
  endpoint: string,
  params: Record<string, string>,
): Promise<T> {
  const url = new URL(`${MAPS_BASE_URL}${endpoint}`);
  url.searchParams.set("key", MAPS_API_KEY);
  for (const [key, value] of Object.entries(params)) {
    if (value !== "") url.searchParams.set(key, value);
  }

  const response = await fetch(url.toString());
  if (!response.ok) {
    throw new Error(`Google Maps HTTP error: ${response.status}`);
  }

  const data = (await response.json()) as T;
  const status = data.status;
  if (status && status !== "OK" && status !== "ZERO_RESULTS") {
    throw new Error(
      `Google Maps API error: ${status}${
        data.error_message ? ` — ${data.error_message}` : ""
      }`,
    );
  }

  return data;
}

