import { mapsRequest } from "./client";

export interface LatLng {
  lat: number;
  lng: number;
}

export interface AddressComponent {
  long_name: string;
  short_name: string;
  types: string[];
}

export interface GeocodingResult {
  place_id: string;
  formatted_address: string;
  geometry: {
    location: LatLng;
    location_type: "ROOFTOP" | "RANGE_INTERPOLATED" | "GEOMETRIC_CENTER" | "APPROXIMATE";
  };
  types: string[];
  address_components: AddressComponent[];
}

interface GeocodingResponse {
  status: "OK" | "ZERO_RESULTS" | "INVALID_REQUEST" | "REQUEST_DENIED" | "OVER_DAILY_LIMIT" | "OVER_QUERY_LIMIT" | "UNKNOWN_ERROR";
  error_message?: string;
  results: GeocodingResult[];
}

/** Convert a human-readable address to coordinates. Returns [] if not found. */
export async function geocodeAddress(
  address: string,
): Promise<GeocodingResult[]> {
  const data = await mapsRequest<GeocodingResponse>("/geocode/json", {
    address,
  });
  return data.results;
}

/** Convert coordinates to the nearest human-readable address. Returns [] if not found. */
export async function reverseGeocode(
  lat: number,
  lng: number,
): Promise<GeocodingResult[]> {
  const data = await mapsRequest<GeocodingResponse>("/geocode/json", {
    latlng: `${lat},${lng}`,
  });
  return data.results;
}

