import { mapsRequest } from "./client";

export interface PlaceSummary {
  place_id: string;
  name: string;
  formatted_address: string;
  geometry: { location: { lat: number; lng: number } };
  types: string[];
  rating?: number;
  user_ratings_total?: number;
  business_status?: string;
}

export interface PlaceDetails extends PlaceSummary {
  formatted_phone_number?: string;
  international_phone_number?: string;
  website?: string;
  opening_hours?: {
    open_now: boolean;
    weekday_text: string[];
  };
  reviews?: Array<{
    author_name: string;
    rating: number;
    text: string;
    time: number;
  }>;
}

export interface AutocompletePrediction {
  place_id: string;
  description: string;
  structured_formatting: {
    main_text: string;
    secondary_text: string;
  };
  types: string[];
}

interface TextSearchResponse {
  status: "OK" | "ZERO_RESULTS" | "INVALID_REQUEST" | "REQUEST_DENIED" | "OVER_DAILY_LIMIT" | "OVER_QUERY_LIMIT" | "UNKNOWN_ERROR";
  error_message?: string;
  results: PlaceSummary[];
  next_page_token?: string;
}

interface PlaceDetailsResponse {
  status: "OK" | "ZERO_RESULTS" | "NOT_FOUND" | "INVALID_REQUEST" | "REQUEST_DENIED" | "UNKNOWN_ERROR";
  error_message?: string;
  result: PlaceDetails;
}

interface AutocompleteResponse {
  status: "OK" | "ZERO_RESULTS" | "INVALID_REQUEST" | "REQUEST_DENIED" | "OVER_DAILY_LIMIT" | "OVER_QUERY_LIMIT" | "UNKNOWN_ERROR";
  error_message?: string;
  predictions: AutocompletePrediction[];
}

export async function searchPlaces(
  query: string,
  options?: { location?: string; radius?: number; type?: string },
): Promise<PlaceSummary[]> {
  const params: Record<string, string> = { query };
  if (options?.location) params.location = options.location;
  if (options?.radius !== undefined) params.radius = String(options.radius);
  if (options?.type) params.type = options.type;
  const data = await mapsRequest<TextSearchResponse>(
    "/place/textsearch/json",
    params,
  );
  return data.results;
}

export async function getPlaceDetails(
  placeId: string,
  fields = "place_id,name,formatted_address,geometry,formatted_phone_number,website,opening_hours,rating,reviews",
): Promise<PlaceDetails> {
  const data = await mapsRequest<PlaceDetailsResponse>(
    "/place/details/json",
    { place_id: placeId, fields },
  );
  return data.result;
}

export async function getAutocompleteSuggestions(
  input: string,
  options?: { location?: string; radius?: number; types?: string },
): Promise<AutocompletePrediction[]> {
  const params: Record<string, string> = { input };
  if (options?.location) params.location = options.location;
  if (options?.radius !== undefined) params.radius = String(options.radius);
  if (options?.types) params.types = options.types;
  const data = await mapsRequest<AutocompleteResponse>(
    "/place/autocomplete/json",
    params,
  );
  return data.predictions;
}

