import { mapsRequest } from "./client";

export type TravelMode = "driving" | "walking" | "bicycling" | "transit";

export interface DirectionsStep {
  html_instructions: string;
  distance: { text: string; value: number };
  duration: { text: string; value: number };
  travel_mode: string;
  start_location: { lat: number; lng: number };
  end_location: { lat: number; lng: number };
}

export interface DirectionsLeg {
  start_address: string;
  end_address: string;
  start_location: { lat: number; lng: number };
  end_location: { lat: number; lng: number };
  distance: { text: string; value: number };
  duration: { text: string; value: number };
  steps: DirectionsStep[];
}

export interface DirectionsRoute {
  summary: string;
  legs: DirectionsLeg[];
  overview_polyline: { points: string };
  warnings: string[];
  copyrights: string;
}

interface DirectionsResponse {
  status: "OK" | "NOT_FOUND" | "ZERO_RESULTS" | "MAX_WAYPOINTS_EXCEEDED" | "INVALID_REQUEST" | "REQUEST_DENIED" | "OVER_DAILY_LIMIT" | "OVER_QUERY_LIMIT" | "UNKNOWN_ERROR";
  error_message?: string;
  routes: DirectionsRoute[];
}

export async function getDirections(
  origin: string,
  destination: string,
  options?: {
    mode?: TravelMode;
    waypoints?: string[];
    alternatives?: boolean;
    /** Unix timestamp or "now" */
    departureTime?: "now" | number;
    avoidTolls?: boolean;
    avoidHighways?: boolean;
    avoidFerries?: boolean;
  },
): Promise<DirectionsRoute[]> {
  const params: Record<string, string> = {
    origin,
    destination,
    mode: options?.mode ?? "driving",
  };
  if (options?.waypoints?.length) {
    params.waypoints = options.waypoints.join("|");
  }
  if (options?.alternatives) params.alternatives = "true";
  if (options?.departureTime !== undefined) {
    params.departure_time = String(options.departureTime);
  }
  const avoid: string[] = [];
  if (options?.avoidTolls) avoid.push("tolls");
  if (options?.avoidHighways) avoid.push("highways");
  if (options?.avoidFerries) avoid.push("ferries");
  if (avoid.length) params.avoid = avoid.join("|");

  const data = await mapsRequest<DirectionsResponse>("/directions/json", params);
  return data.routes;
}

