import { mapsRequest } from "./client";
import type { TravelMode } from "./directions";

export interface DistanceMatrixElement {
  status: "OK" | "NOT_FOUND" | "ZERO_RESULTS";
  distance?: { text: string; value: number };
  duration?: { text: string; value: number };
  duration_in_traffic?: { text: string; value: number };
}

export interface DistanceMatrixRow {
  elements: DistanceMatrixElement[];
}

export interface DistanceMatrixResult {
  origin_addresses: string[];
  destination_addresses: string[];
  rows: DistanceMatrixRow[];
}

interface DistanceMatrixResponse extends DistanceMatrixResult {
  status: "OK" | "INVALID_REQUEST" | "MAX_ELEMENTS_EXCEEDED" | "REQUEST_DENIED" | "OVER_DAILY_LIMIT" | "OVER_QUERY_LIMIT" | "UNKNOWN_ERROR";
  error_message?: string;
}

export async function getDistances(
  origins: string[],
  destinations: string[],
  options?: {
    mode?: TravelMode;
    /** Unix timestamp or "now" */
    departureTime?: "now" | number;
    units?: "metric" | "imperial";
    avoidTolls?: boolean;
    avoidHighways?: boolean;
  },
): Promise<DistanceMatrixResult> {
  const params: Record<string, string> = {
    origins: origins.join("|"),
    destinations: destinations.join("|"),
    mode: options?.mode ?? "driving",
    units: options?.units ?? "metric",
  };
  if (options?.departureTime !== undefined) {
    params.departure_time = String(options.departureTime);
  }
  const avoid: string[] = [];
  if (options?.avoidTolls) avoid.push("tolls");
  if (options?.avoidHighways) avoid.push("highways");
  if (avoid.length) params.avoid = avoid.join("|");

  const { status: _status, error_message: _err, ...result } =
    await mapsRequest<DistanceMatrixResponse>("/distancematrix/json", params);
  return result;
}

