import { MAPS_API_KEY } from "./client";

export interface StaticMapMarker {
  /** Address or "lat,lng" */
  location: string;
  color?: string;
  size?: "tiny" | "small" | "mid";
  /** Single uppercase letter or digit */
  label?: string;
  icon?: string;
}

export interface StaticMapOptions {
  /** Address or "lat,lng" — required unless markers are provided */
  center?: string;
  /** 0–21 */
  zoom?: number;
  /** "widthxheight" in pixels, e.g. "600x400" */
  size?: string;
  scale?: 1 | 2;
  maptype?: "roadmap" | "satellite" | "terrain" | "hybrid";
  markers?: StaticMapMarker[];
  /** Encoded polyline path */
  path?: string;
  format?: "png" | "jpg" | "gif";
}

/**
 * Builds a Google Static Maps image URL.
 *
 * The URL itself is the API request — pass it to an <img> src or fetch it
 * server-side to get the raw image bytes.
 */
export function buildStaticMapUrl(options: StaticMapOptions = {}): string {
  const url = new URL("https://maps.googleapis.com/maps/api/staticmap");
  url.searchParams.set("key", MAPS_API_KEY);

  if (options.center) url.searchParams.set("center", options.center);
  if (options.zoom !== undefined)
    url.searchParams.set("zoom", String(options.zoom));
  url.searchParams.set("size", options.size ?? "600x400");
  if (options.scale) url.searchParams.set("scale", String(options.scale));
  if (options.maptype) url.searchParams.set("maptype", options.maptype);
  if (options.format) url.searchParams.set("format", options.format);
  if (options.path) url.searchParams.set("path", options.path);

  for (const marker of options.markers ?? []) {
    const parts: string[] = [];
    if (marker.icon) {
      parts.push(`icon:${marker.icon}`);
    } else {
      if (marker.color) parts.push(`color:${marker.color}`);
      if (marker.size) parts.push(`size:${marker.size}`);
      if (marker.label) parts.push(`label:${marker.label}`);
    }
    parts.push(marker.location);
    url.searchParams.append("markers", parts.join("|"));
  }

  return url.toString();
}
